        validmin = attrs.get('VALIDMIN', None)
        validmax = attrs.get('VALIDMAX', None)

        data = cdf.varget(v)
        arr = np.array(data)

        num_stats = {'min': None, 'max': None, 'nan_frac': None, 'unique_approx': None}
        if np.issubdtype(arr.dtype, np.number):
            a = arr.astype('float64', copy=False)
            if fill is not None:
                try:
                    fv = float(np.array(fill).ravel()[0])
                    a = np.where(a == fv, np.nan, a)
                except Exception:
                    pass
