                if np.isfinite(np.nanmax(a)):
                    num_stats['max'] = float(np.nanmax(a))
            try:
                # approximate uniqueness by sampling
                flat = a.ravel()
                flat = flat[np.isfinite(flat)]
                if flat.size > 0:
                    samp = flat[::max(1, flat.size // 10000)]
                    num_stats['unique_approx'] = int(pd.Series(samp).nunique())
            except Exception:
                pass

        rows.append({
            'var': v,
            'var_group': 'r' if v in rvars else 'z',
            'DataType': vi.get('DataType', None),
            'NumElements': vi.get('NumElements', None),
