def load() -> pd.DataFrame:
    import numpy as np
    import pandas as pd
    from cdflib import CDF

    path = 'data/astronomy/input/swarm/SW_OPER_ACCACAL_2__20240511T000000_20240511T235959_0304.cdf'
    cdf = CDF(path)

    rows = []
    for var in ['a_aa','a_cal','a_tmp','a_ca','a_gg']:
        try:
            data = cdf.varget(var)
            arr = np.asarray(data)
            rows.append({
                'var': var,
                'dtype': str(arr.dtype),
                'ndim': arr.ndim,
                'shape': str(arr.shape),
                'min': float(np.nanmin(arr)) if np.size(arr)>0 else np.nan,
                'max': float(np.nanmax(arr)) if np.size(arr)>0 else np.nan,
                'unique_approx': int(len(np.unique(arr[:min(arr.shape[0],2000)]))) if arr.ndim==1 else int(len(np.unique(arr[:min(arr.shape[0],2000),:].ravel())))
            })
        except Exception as e:
            rows.append({'var': var, 'dtype': None, 'ndim': None, 'shape': None, 'min': None, 'max': None, 'unique_approx': None, 'error': str(e)})

    return pd.DataFrame(rows)
